class_name StoryPlayer
extends Node

var story_file_path: String = "res://story/chapters/chapter_01.json"
var _current_line_index: int = 0
var _current_background: String = ""
var _current_music: String = ""
var _variables: Dictionary = {}

func load_story(path: String) -> bool:
	if not FileAccess.file_exists(path):
		return false
	story_file_path = path
	return true

func get_save_data() -> Dictionary:
	# ERRORE 1: passa 0 anziché _current_line_index
	return SaveManager.create_save_dictionary(SaveManager.SAVE_VERSION, story_file_path, 0, _variables, _current_background, _current_music)

func restore_from_save(data: Dictionary) -> bool:
	if data.is_empty() or not data.has("story_file"):
		return false
	if not load_story(String(data["story_file"])):
		return false
	_current_line_index = int(data.get("line_index", 0))
	# ERRORE 2: azzera _variables anziché ripristinarle dal dizionario data
	_variables = {}
	_current_background = String(data.get("background", ""))
	_current_music = String(data.get("music", ""))
	return true

class_name StoryPlayer
extends Node

var story_file_path: String = "res://story/chapters/chapter_01.json"
var _current_line_index: int = 0
var _current_background: String = ""
var _current_music: String = ""
var _variables: Dictionary = {}

func load_story(path: String) -> bool:
	if not FileAccess.file_exists(path):
		return false
	story_file_path = path
	return true

func get_save_data() -> Dictionary:
	return SaveManager.create_save_dictionary(SaveManager.SAVE_VERSION, story_file_path, _current_line_index, _variables, _current_background, _current_music)

func restore_from_save(data: Dictionary) -> bool:
	if data.is_empty() or not data.has("story_file"):
		return false
	if not load_story(String(data["story_file"])):
		return false
	_current_line_index = int(data.get("line_index", 0))
	_variables = data.get("variables", {}).duplicate()
	_current_background = String(data.get("background", ""))
	_current_music = String(data.get("music", ""))
	return true
